import {
  Component,
  ComponentInterface,
  Element,
  Event,
  EventEmitter,
  h,
  Host,
  Listen,
  Prop,
  State,
  Watch,
} from '@stencil/core';

/**
 * @slot default - default slot for the content of the select-option
 * @slot description - slot for descriptive text. only available for expandable groups
 */
@Component({
  tag: 'groupui-multiselect-option-group',
  styleUrl: 'multiselect-option-group.scss',
  shadow: true,
})
export class MultiselectOptionGroup implements ComponentInterface {
  /**
   * Multiselect Group Label String
   */
  @Prop({ reflect: true }) readonly label: string;

  /**
   * Whether the group is expandable. When it is true, the group gets an own checkbox and can be collapsed and selected
   */
  @Prop({ reflect: true }) readonly expandable: boolean = false;

  /**
   * Whether the group is collapsed and hiding its children
   */
  @Prop({ mutable: true, reflect: true }) collapsed: boolean = false;

  /**
   * use this only with a searchable multiselect, hides the option
   */
  @Prop({ reflect: true }) readonly invisible: boolean = false;

  /**
   * dispatched when collapsed state changes. Emits true when the group was collapsed, false when it was expanded
   */
  @Event({ composed: false }) groupuiCollapsedChanged: EventEmitter<boolean>;

  /**
   * dispatched when the checked state of the parent checkbox changes.
   */
  @Event({ composed: false }) groupuiParentCheckedChanged: EventEmitter<boolean>;

  @Element() host: HTMLElement;

  @State() parentChecked: boolean = false;
  @State() indeterminate: boolean = false;
  @State() childOptions: HTMLGroupuiMultiselectOptionElement[] = [];

  private observer: MutationObserver;

  @Watch('collapsed')
  onCollapsedChange() {
    this.groupuiCollapsedChanged.emit(this.collapsed);
  }

  componentDidLoad() {
    if (!this.expandable) return;
    // Setup mutation observer to detect added/removed child checkboxes
    this.observer = new MutationObserver(() => {
      this.findOptions();
      this.applyIndentation();
      this.updateParentState();
    });

    this.observer.observe(this.host, {
      childList: true,
      subtree: true,
      attributes: true,
      attributeFilter: ['checked'],
    });
  }

  componentWillLoad() {
    if (!this.expandable) return;
    // Initialize child checkboxes and parent state before first render
    this.findOptions();
    this.applyIndentation();
    this.updateParentState();
  }

  disconnectedCallback() {
    this.observer?.disconnect();
  }

  private toggleCollapsed = () => {
    this.collapsed = !this.collapsed;
  };

  @Listen('click', { capture: true })
  handleClick(event: MouseEvent) {
    if (!this.expandable) return;
    const isKeyboardEvent = event.isTrusted === false;

    if (isKeyboardEvent) {
      // Handle programmatic click - directly click the parent checkbox
      event.preventDefault();
      event.stopPropagation();
      const parentCheckbox = this.host.shadowRoot.querySelector('#parent-checkbox') as HTMLElement;
      parentCheckbox.dispatchEvent(new MouseEvent('click', { bubbles: false, composed: false }));
    }
  }

  private applyIndentation() {
    this.childOptions.forEach((option) => {
      option.classList.add('group-indentation');
    });
  }

  private findOptions() {
    // Direct query all checkbox elements in the light DOM
    this.childOptions = Array.from(this.host.querySelectorAll('groupui-multiselect-option'));
  }

  private updateParentState() {
    if (!this.childOptions.length) {
      this.parentChecked = false;
      this.indeterminate = false;
      return;
    }

    const checkedCount = this.childOptions.filter((checkbox) => checkbox.checked).length;

    if (checkedCount === 0) {
      this.parentChecked = false;
      this.indeterminate = false;
    } else if (checkedCount === this.childOptions.length) {
      this.parentChecked = true;
      this.indeterminate = false;
    } else {
      this.parentChecked = false;
      this.indeterminate = true;
    }
  }

  private readonly handleParentCheckboxChange = () => {
    const newCheckedState = !this.parentChecked;

    // If indeterminate, always set to checked first
    if (this.indeterminate) {
      this.parentChecked = true;
      this.indeterminate = false;
    } else {
      this.parentChecked = newCheckedState;
    }

    this.groupuiParentCheckedChanged.emit(this.parentChecked);
  };

  private isDescriptionSlotProvided(): boolean {
    return !!this.host.querySelector('[slot="description"]');
  }

  render() {
    if (!this.expandable) {
      return (
        <Host tabindex={-1}>
          <div id="label">{this.label}</div>
          <slot />
        </Host>
      );
    }
    return (
      <Host tabIndex={-1}>
        <div class="checkbox-group">
          <div class="accordion">
            <div class="accordion-header" id="accordion-header">
              <span class="header-content">
                <div class="checkbox-container">
                  <groupui-checkbox
                    tabIndex={-1}
                    checked={this.parentChecked}
                    onChange={this.handleParentCheckboxChange}
                    id="parent-checkbox"
                    indeterminate={this.indeterminate}
                  >
                    <span id="label">{this.label}</span>
                    {this.isDescriptionSlotProvided() && <slot name="description" />}
                  </groupui-checkbox>
                </div>
              </span>

              <groupui-icon
                class={{
                  'accordion-icon': true,
                  expanded: !this.collapsed,
                }}
                name="chevron-down-24"
                aria-expanded={!this.collapsed ? 'true' : 'false'}
                aria-controls="accordion-content"
                onClick={this.toggleCollapsed}
                role="button"
                id="accordion-icon"
              />
            </div>
            <section
              id="accordion-content"
              class="accordion-content"
              aria-hidden={this.collapsed ? 'true' : null}
              aria-labelledby="label"
              style={this.collapsed ? { display: 'none' } : null}
            >
              <div class="children-container">
                <slot></slot>
              </div>
            </section>
          </div>
        </div>
      </Host>
    );
  }
}
